INSERT INTO source_chunks(id, title, url, source_family, path, body, description) VALUES (226, 'Awards', 'https://radiona.org/about/awards-2/', 'radiona', 'Sources/Raw/radiona/page-2332-awards.md', '# Awards Awards 2025 – The Audience Choice Award for installation RotoMotoMuzik @ Festival of the First 2025. – The Main prize of the Festival for installation Objects and Connotations @ Festival of the First 2025. – Relentless Freedom Penguin Award @ DORS/CLUC 2025 – Croatian Linux Users’ Conference. 2016 – Synthomir synthesizer – special mention in […] Awards 2025 – The Audience Choice Award for installation RotoMotoMuzik @ Festival of the First 2025. – The Main prize of the Festival for installation Objects and Connotations @ Festival of the First 2025. – Relentless Freedom Penguin Award @ DORS/CLUC 2025 – Croatian Linux Users’ Conference. 2016 – Synthomir synthesizer – special mention in the category of product design – professional selection by Croatian design professionals within the competition of the Croatian Biennial Design Exhibition. NOMINATIONS ONLY: 2025 – Ambassador Award in Music Professional Industry by Klupska scena (Clubbing Scene web portal) in the category Longterm Contribution to the Scene – Audience votes.', '# Awards Awards 2025 – The Audience Choice Award for installation RotoMotoMuzik @ Festival of the First 2025. – The Main prize of the Festival for installation Objects and Connotations @ Festival of the First 2025. – Relentless Freedom Penguin Award @ DORS/CLUC 2025 – Croatian Linux Users’ Conference. 2016 – Synthomir synthesizer – special mention in […] Awards 2025 – The Audience Choice Award for installation RotoMotoMuzik @ Festival of the First 2025. – The Main prize of the Festival for installation Objects and Connotations @ Festival of the First 2025. – Relentless Freedom Penguin Award @ DORS/CLUC 2025 – Croatian Linux Users’ Conference. 2016 – Synthomir synthesizer – special mention in the category of product design – professional selection by Croatian design professionals within the competition of the Croatian Biennial Design Exhibition. NOMINATIONS ONLY: 2025 – Ambassador Award i');
INSERT INTO source_chunks_fts(title, body, path, source_family, url) VALUES ('Awards', '# Awards Awards 2025 – The Audience Choice Award for installation RotoMotoMuzik @ Festival of the First 2025. – The Main prize of the Festival for installation Objects and Connotations @ Festival of the First 2025. – Relentless Freedom Penguin Award @ DORS/CLUC 2025 – Croatian Linux Users’ Conference. 2016 – Synthomir synthesizer – special mention in […] Awards 2025 – The Audience Choice Award for installation RotoMotoMuzik @ Festival of the First 2025. – The Main prize of the Festival for installation Objects and Connotations @ Festival of the First 2025. – Relentless Freedom Penguin Award @ DORS/CLUC 2025 – Croatian Linux Users’ Conference. 2016 – Synthomir synthesizer – special mention in the category of product design – professional selection by Croatian design professionals within the competition of the Croatian Biennial Design Exhibition. NOMINATIONS ONLY: 2025 – Ambassador Award in Music Professional Industry by Klupska scena (Clubbing Scene web portal) in the category Longterm Contribution to the Scene – Audience votes.', 'Sources/Raw/radiona/page-2332-awards.md', 'radiona', 'https://radiona.org/about/awards-2/');
